local SettingMgr = SettingMgr:GetInstance()

---@class GamePlayGuideConfMgr
local GamePlayGuideConfMgr = {}

function GamePlayGuideConfMgr:Init()
    self.arrGuideData = nil
end

function GamePlayGuideConfMgr:Delete()
    self.arrGuideData = nil
end

function GamePlayGuideConfMgr:FillData(questId)
    self.arrGuideData = {}
    local tf = SettingMgr:Get(string.format("%s%s", AutoIds.IdSetting1001, "IDGroup"))
    local tableSettings = tf:GetAll()
    for i, v in pairs(tableSettings) do
        local guideId = parse_string(v, "guideId")
        local strings = string.split(guideId, "_")
        local questIndex = checkInt(strings[1])
        local questWave = checkInt(strings[2])
        local questRound = checkInt(strings[3])   -- 这里的回合数，不是战斗内显示的回合数，而是从当前波次开始以后的第几个回合
        if questId == checkInt(questIndex) then
            local ids = parse_string(v, "ids")
            local arrId = string.split(ids, ",")
            for i = 1, #arrId do
                if isNull(self.arrGuideData[questWave]) then
                    self.arrGuideData[questWave] = {}
                end
                if isNull(self.arrGuideData[questWave][questRound]) then
                    self.arrGuideData[questWave][questRound] = {}
                end
                table.insert(self.arrGuideData[questWave][questRound], checkInt(arrId[i]))
            end
        end
    end
end

---GetGuideStepData
---获取 引导步骤数据
---@param stepId number @ 步骤 Id
function GamePlayGuideConfMgr:GetGuideStepData(stepId)
    local setting = SettingMgr:GetSetting(AutoIds.IdSetting1001, "GuideDescConfVo")
    return setting:Get(stepId)
end

function GamePlayGuideConfMgr:GetGuideData()
    return self.arrGuideData
end

return GamePlayGuideConfMgr